INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (22,11,'Global',0,'Federal Reserve Raises Rates and Points to Further Tightening.','Reuters','16 Sept 2026',NULL,'The Federal Reserve raised its target range by 25 basis points to 3.75%-4.00%, its first increase since 2023, and pointed to further tightening.','Negative','Negative. A wider US rate gap pressures the ringgit and lifts Bank Muamalat’s dollar funding cost and DRB-HICOM’s hedging cost.','Next Federal Open Market Committee (FOMC) meeting 27-28 Oct.',NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (23,11,'Global',1,'Strait of Hormuz Traffic Falls to Three Vessels as Conflict Intensifies.','Reuters','17 Sept 2026',NULL,'Ship-tracking data recorded three vessel transits on 16 Sept, versus 12 the previous day and a ten-day average of 17.','Negative','Negative. Thin traffic keeps war-risk premiums and delay risk high for any Group cargo routed through the Gulf.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (24,11,'Global',2,'Iran War Pushes US-to-Asia Crude-Tanker Cost to a Record USD44.8 mn.','The Star','17 Sept 2026',NULL,'The cost of carrying two mn barrels from the US Gulf Coast to China rose to USD44.8 mn from USD17.8 mn before the war. The quote applies to crude tankers, not containers or dry bulk.','Negative','Negative. Record crude freight lifts delivered oil costs across Asia. Malakoff’s fleet runs mainly on coal and gas, so crude freight reaches it only indirectly.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (25,11,'Global',3,'Saudi Pipeline Damage Extends Crude Rerouting through Oman.','Reuters','16 and 17 Sept 2026',NULL,'Three East-West Pipeline pumping stations were damaged, with repairs estimated at five to six weeks and partial operations possible sooner. Separately, Saudi Aramco offered Asian buyers crude via ship-to-ship transfers off Sohar.','Mixed','Mixed. Oman loadings keep crude moving, at the cost of longer routes and higher handling costs. No direct Group channel identified.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (26,11,'Asia Pacific',4,'China’s Industrial Output Accelerates as Domestic Demand Weakens.','Reuters','15 Sept 2026',NULL,'Industrial production rose 5.2% yoy in Aug from 4.5% in Jul, while retail sales slowed to 0.4% and fixed-asset investment contracted 7.2% over Jan-Aug.','Mixed','Mixed. Firmer factory output supports regional supply chains; weak retail and falling investment cap China’s import demand. Limited direct Group impact.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (27,11,'Asia Pacific',5,'Singapore Exports Rise 46.2% yoy on Artificial Intelligence Demand.','Reuters','17 Sept 2026',NULL,'Aug non-oil domestic exports rose 46.2% yoy; electronics rose 131.8%, partly from a low base. Enterprise Singapore raised its 2026 forecast to 14%-16%.','Positive','Positive. The AI export boom is the demand backdrop for Johor logistics, Tanjung Bin Industrial Park (TBIP) and Senai Airport City (SAC); no new Group volumes or tenant enquiries are confirmed yet.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (28,11,'Asia Pacific',6,'High LNG Prices Push Asia’s Sept Imports to an Eight-Year Low.','Reuters','17 Sept 2026',NULL,'Sept imports are estimated at 20.09 mn tonnes as North Asian spot prices reached USD26 per mmBtu, with cargoes diverted to Europe.','Negative','Negative. Higher spot LNG raises regional gas costs. Malakoff’s fuel bill rises only if spot cargoes enter its gas supply; Gas Malaysia passes costs through the reference price with a lag.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (29,11,'Asia Pacific',7,'BOJ Raises Policy Rate to a 31-Year High.','Bank of Japan','18 Sept 2026',NULL,'The BOJ decided by a 7-2 vote to raise the uncollateralised overnight call-rate guideline from 1.00% to 1.25%, effective 24 Sept. The yen weakened after the decision.','Mixed','Mixed. Higher yen rates raise the cost of any unhedged yen borrowing at DRB-HICOM; the effect on Japanese component costs turns on the yen-ringgit rate.','Next BOJ meeting 29-30 Oct.',NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (30,11,'Malaysia Macro',8,'Brent Crude (18 Sept settlement) (Weekly Macro Pulse indicator)','Weekly Macro Pulse indicator','18 Sept 2026',NULL,'Current: USD104.87/bbl | Previous: USD104.61/bbl | Direction: ↑ 0.25% week on week (wow)','Neutral','Neutral. Brent held above USD100 for a second week. Malakoff’s fuel cost tracks mainly coal and gas, not Brent directly; Gas Malaysia’s reference price follows with a lag',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (31,11,'Malaysia Macro',9,'USD/MYR (BNM 5.00 pm closing rate, 18 Sept) (Weekly Macro Pulse indicator)','Weekly Macro Pulse indicator','18 Sept 2026',NULL,'Current: 4.0808 | Previous: 4.0685 | Direction: ↑ 0.30% wow ringgit weaker','Mixed','Mixed. Unhedged dollar import costs rise; the Fed hike keeps pressure on the ringgit',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (32,11,'Malaysia Macro',10,'CNY/MYR (BNM 5.00 pm closing rate, 18 Sept) (Weekly Macro Pulse indicator)','Weekly Macro Pulse indicator','18 Sept 2026',NULL,'Current: 0.6092 | Previous: 0.6064 | Direction: ↑ 0.46% wow ringgit weaker','Negative','Negative. China-sourced inputs cost more for unhedged importers, a faster move than against the dollar',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (33,11,'Malaysia Macro',11,'Unsubsidised Fuel Prices per Litre (Weekly Macro Pulse indicator)','Weekly Macro Pulse indicator','18 Sept 2026',NULL,'Current: RON95: RM4.37; RON97: RM4.85; Peninsular diesel: RM5.27 | Previous: RON95: RM4.02; RON97: RM4.50; Peninsular diesel: RM4.92 | Direction: ↑ 35 sen each','Negative','Negative. Up 60 sen/litre in two weeks. Hits unsubsidised fleet volumes at Pos Malaysia, Kontena Nasional and Tradewinds Plantation until surcharges catch up',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (34,11,'Malaysia Macro',12,'10-Year MGS Yield  (18 Sept close) (Weekly Macro Pulse indicator)','Weekly Macro Pulse indicator','18 Sept 2026',NULL,'Current: 3.92% | Previous: 4.18% | Direction: ↓ 26 basis points','Positive','Positive. The 26-basis-point decline lowers the sovereign benchmark; Bank Muamalat’s realised benefit depends on its funding mix',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (35,11,'Malaysia Macro',13,'FTSE Bursa Malaysia Kuala Lumpur Composite Index (FBM KLCI; 18 Sept close) (Weekly Macro Pulse indicator)','Weekly Macro Pulse indicator','18 Sept 2026',NULL,'Current: 1,665.56 | Previous: 1,686.74 | Direction: ↓ 1.26% wow','Neutral','Neutral. No read-through for Group companies',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (36,11,'Malaysia Macro',14,'Net Foreign Flow (Weekly Macro Pulse indicator)','Weekly Macro Pulse indicator','18 Sept 2026',NULL,'Current: RM160.3 mn outflow, week ended 11 Sept | Previous: RM640.3 mn outflow, week ended 4 Sept | Direction: ↓ RM480.0 mn narrower; down 75.0%','Mixed','Mixed. Sixth straight week of foreign selling, at a quarter of the prior week’s pace; local institutions also sold',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (37,11,'Malaysia Macro',15,'MBSB Research Sees a 25-Basis-Point OPR Hike in 2027.','The Star/Bernama','18 Sept 2026',NULL,'MBSB Research expects Bank Negara Malaysia may raise the overnight policy rate (OPR) by 25 basis points in 2027 amid further global rate increases. BNM has made no policy change.','Neutral','Neutral. A research view, not policy. A hike would lift Bank Muamalat’s deposit and vehicle-financing rates together; the margin effect turns on which reprices faster.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (38,11,'Malaysia Macro',16,'Malaysia’s Aug Exports Rise 45.5% yoy.','The Star/Bernama','18 Sept 2026',NULL,'Exports rose 45.5% yoy to RM191.05 bn, total trade rose 43.4% to RM354.01 bn and imports rose 41.1% to RM162.96 bn. The trade surplus reached RM28.09 bn, the 76th consecutive monthly surplus.','Positive','Positive. Electrical and electronics (E&E)-led export growth is the volume backdrop for MMC Ports.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (39,11,'Malaysia Macro',17,'Malaysia’s Aug Inflation Rises to 1.9%.','The Star/Bernama','18 Sept 2026',NULL,'Consumer prices rose 1.9% yoy in Aug, from 1.8% in Jul. Transport inflation increased to 2.0% from 1.4%, while housing and utilities increased to 2.1% from 1.8%.','Mixed','Mixed. Transport and housing, the fastest-rising components, feed straight into Group operating costs.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (40,11,'Ports/Infrastructure/Logistics',18,'Bintulu Port Sdn Bhd Appointed Operator for 30 Years.','The Star','17 Sept 2026',NULL,'Bintulu Port Sdn Bhd was appointed terminal operator for 30 years under a Heads of Agreement, pending execution of the Port Operation Concession Agreement.','Neutral','Neutral. A 30-year state-port appointment sets a tenure benchmark for MMC Ports; tariff and risk terms sit in the concession agreement, still unsigned.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (41,11,'Ports/Infrastructure/Logistics',19,'MASkargo, IAG Cargo and Qatar Airways Cargo Complete First Joint Shipment Trial.','The Star','17 Sept 2026',NULL,'The three carriers completed their first customer shipment trial under a joint cargo arrangement, extending interlinked capacity across Europe, the Middle East and Asia.','Neutral','Neutral. More interlined cargo capacity through Kuala Lumpur; Pos Aviation gains only if it handles the participating carriers.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (42,11,'Automotive/Services',20,'Proton e.MAS Sells 6,047 Vehicles in Aug.','PRO-NET','8 Sept 2026',NULL,'Proton New Energy Technology (PRO-NET) reported 6,047 vehicles sold in Aug, including 5,999 domestic registrations.',NULL,'Positive for Proton’s electric-vehicle (EV) business; margins depend on mix, costs and incentives. Bank Muamalat financing depends on applications and approvals.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (43,11,'Automotive/Services',21,'Carsome Opens MV15 Centre; Fees Remain Regulated.','The Edge','14 Sept 2026',NULL,'Carsome Academy launched an MV15 ownership-transfer inspection centre at the Carsome Dealer Hub in Sungai Buloh on 14 Sept. It is the first MV15 centre operated by an automotive technical and vocational education and training institution. Inspections take less than 20 minutes, with results transmitted directly to the Road Transport Department (JPJ) system.','Mixed','Mixed. Fees are fixed, so rival centres compete with Puspakom on speed, convenience and coverage rather than price.','MV15 fees stay fixed by JPJ; Transport Ministry and JPJ audits continue.',NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (44,11,'Automotive/Services',22,'Tan Chong Signs a Three-Year Agreement to Support Perodua BEV Production.','The Edge','14 Sept 2026',NULL,'Tan Chong provides coating, painting, assembly-line rental and related services for Perodua’s Serendah battery electric vehicles (BEVs), from 1 June 2026 to 31 May 2029, with a two-year extension option. Signed 12 Sept, formalising a November 2025 letter of intent.','Negative','Negative. Extra assembly capacity lets Perodua scale its battery EV against Proton’s e.MAS range.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (45,11,'Automotive/Services',23,'Malaysia’s Aug Vehicle Sales Fall 2% yoy.','The Star/Bernama','18 Sept 2026',NULL,'Total industry volume fell 2% yoy to 71,428 units and 3% month on month (mom). Passenger-vehicle sales were 67,058, while commercial-vehicle sales fell 24% yoy to 4,370. Jan-Aug volume rose 3% to 530,478.','Mixed','Mixed. The market shrank 2% yoy while Proton took an estimated 27.9% share in Aug; the 24% fall in commercial vehicles is the weak spot.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (46,11,'Automotive/Services',24,'Tan Chong and Saike Study Local EV Battery Packs.','The Star','18 Sept 2026',NULL,'TQ Manufacturing, a Tan Chong Motor unit, signed a 12-month memorandum with China’s Saike REPT Power Battery System to study local EV battery-pack assembly for TQ Wuling and export, plus recycling and second-life use. Any binding deal depends on the study.','Mixed','Mixed. Local packs would cut TQ Wuling’s costs and sharpen competition for Proton; also a reference point for Group battery sourcing. Nothing is committed.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (47,11,'Agriculture/Food Security',25,'Malaysia Raises the Oct Crude Palm Oil Reference Price while Duty Stays at 10%.','The Edge','15 Sept 2026',NULL,'The Oct reference price rose to RM4,452.66 per tonne from RM4,392.32, with the export duty held at 10%.','Mixed','Mixed. The reference price sets the duty, not Tradewinds Plantation’s realised price. At 10%, duty rises about RM6.03/tonne.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (48,11,'Agriculture/Food Security',26,'Ministry Backs Bernas Mill’s 46.2% Padi Deduction After Farmer Complaint.','Bernama','15 Sept 2026',NULL,'The Ministry of Agriculture and Food Security (KPKM) said grading at the Bernas mill in Bukit Kenak, Terengganu, met Malaysian Standard MS 84:2017, after a farmer’s video over a 46.2% deduction went viral. Immature grains (23.8%), wet padi (10.6%) and empty grains (11.8%) drove the deduction; the farmers’ representative had signed the quality certificate.','Negative','Negative. The ministry cleared Bernas on procedure, but grading disputes at the start of the Season 2/2026 harvest put Tradewinds’ rice arm under public scrutiny.','KPKM has ordered Padi and Rice Regulatory inspectors to monitor mills in states approaching harvest.',NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (49,11,'Energy/Power/Sustainability',27,'Gas Malaysia and Air Liquide Engineering & Construction Explore Low-Carbon Projects.','Bernama','17 Sept 2026',NULL,'Gas Malaysia and Air Liquide Engineering & Construction signed a memorandum covering low-carbon hydrogen, carbon-dioxide off-take and Bio-LNG opportunities.','Neutral','Neutral. An early step in Gas Malaysia’s low-carbon push, and a possible Bio-LNG outlet for Tradewinds Plantation mill residues; nothing is committed.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (50,11,'Energy/Power/Sustainability',28,'PETRONAS and PTT Secure a 35-Year Gas-Block Contract.','Reuters','14 Sept 2026',NULL,'The 35-year contract, retroactive to 1 Jan 2026, covers Block A-18 plus adjacent acreage and runs past the current contract’s 2029 expiry. The 700 mn standard cubic feet/day is existing A-18-01 and B-17-01 capacity, shared equally by Malaysia and Thailand, not new output.','Neutral','Neutral. Secures existing gas supply past 2029; no direct allocation to Malakoff or Gas Malaysia identified.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (51,11,'Energy/Power/Sustainability',29,'New 250 MW Feed-in Tariff Quota for 2027 Targets RM3 bn of Investment.','The Edge','15 Sept 2026',NULL,'Ministry of Energy Transition and Water Transformation (PETRA) announced 250 megawatts (MW) for 2027: 30 MW biogas, 120 MW biomass and 100 MW small hydro; supply may start in 2030.','Positive','Positive. The biogas and biomass quotas open bids for Malakoff and for Tradewinds Plantation’s mill feedstock; returns turn on the tariffs won and grid access.','E-bidding: 3 Feb-24 Mar 2027, covering Peninsular Malaysia and Labuan.',NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (52,11,'Energy/Power/Sustainability',30,'UOB Kay Hian Expects a CRESS Charge Cut for Firm Renewables with Storage.','The Star','17 Sept 2026',NULL,'UOB Kay Hian expects the system access charge for firm renewables with storage to fall from 20 sen/kWh to 15 sen/kWh. The RM14 bn figure is an indicative decade-long opportunity, not orders.','Mixed','Mixed. A confirmed cut widens the market for Malakoff and MMC Engineering; TBIP and SAC still need grid, storage and offtake in place.','No change to Corporate Renewable Energy Supply Scheme (CRESS) access charges has been announced.',NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (53,11,'Energy/Power/Sustainability',31,'B.Grimm Orders a Gas Turbine for a New Perlis Power Plant.','Reuters','15 Sept 2026',NULL,'B.Grimm Power signed gas turbine supply agreements with GE Vernova for a new Perlis power plant, scheduled for commercial operation in the fourth quarter of 2029, targeting rising electricity demand including from data centres.','Neutral','Neutral. Adds gas-fired capacity for northern demand, including data centres, and a future rival to Malakoff in capacity awards.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (54,11,'Energy/Power/Sustainability',32,'Malaysia Targets Q4 2027 Nuclear Readiness Review.','IAEA','16 Sept 2026',NULL,'The 16 Sept International Atomic Energy Agency (IAEA) statement names the Malaysia Power Industry Corporation (MyPOWER) as coordinator and targets a Phase 1 review in Q4 2027.','Neutral','Neutral. The Q4 2027 Phase 1 review sets the timetable for Malakoff and MMC Engineering to line up roles and partners.','Preparatory work; no plant approval announced.',NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (55,11,'Energy/Power/Sustainability',33,'Malaysia Needs 14-17 GW of Additional Power Capacity and up to RM95 bn of Investment.','The Star','17 Sept 2026',NULL,'Moody’s estimates Malaysia needs 14-17 gigawatts (GW) of new capacity and up to RM95 bn of investment, mostly gas-fired at 50%-60% load factors. Separately, 13 GW of power purchase agreements (PPAs) expire in 2026-2035.','Positive','Positive. A large award pipeline for Malakoff and MMC Engineering; expiring PPAs may be extended rather than closed. Gas Malaysia has no assured allocation.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (56,11,'Property',34,'EcoWorld Secures S$208.1 mn Singapore Residential Site.','The Star','18 Sept 2026',NULL,'Singapore’s Urban Redevelopment Authority awarded the 99-year residential site to EcoWorld’s wholly owned Singapore subsidiary for S$208.1 mn (RM667.6 mn). EcoWorld plans to launch its first Singapore development in 2028, funded through bank borrowings and/or internal funds.','Positive','Positive. EcoWorld’s first Singapore development; Group exposure is through Syed Mokhtar AlBukhary’s 30.1% indirect stake. Returns turn on build costs and sales at the 2028 launch.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (57,11,'Aviation',35,'AirAsia Says Demand Remains Strong as Government Monitors Financial Health.','Reuters','18 Sept 2026',NULL,'AirAsia reported an 80% third-quarter load factor and said demand remained strong despite elevated fuel costs and financial pressures. Separately, the government asked Malaysia Airlines and Batik Air about their capacity to absorb AirAsia’s domestic market share as part of contingency planning.','Negative','Negative. Senai Airport is AirAsia’s operating base, so route cuts would hit its traffic first; other carriers may backfill part of it. Pos Aviation’s exposure is limited to confirmed AirAsia contracts.','No regulatory action. The government has engaged Alton Aviation to assess AirAsia’s funding needs.',NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (58,11,'Aviation',36,'Malaysia’s Aerospace Industry Moves up the Value Chain.','The Star','17 Sept 2026',NULL,'In 2025, Malaysia’s aerospace industry generated RM32.5 bn in revenue, with more than 34,700 skilled workers and over 250 companies.','Positive','Positive. A deeper supplier base broadens SAC’s potential tenant pool and expands opportunities for DRB-HICOM’s defence and aviation businesses.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (59,11,'Banking/Financial Services',37,'Japan and Malaysia Sign a USD6 bn Bilateral Swap Arrangement.','BNM','15 Sept 2026',NULL,'Effective 18 Sept, the swap provides up to USD6 bn or yen equivalent. Both parties can exchange local currency for dollars; BNM can also obtain yen.','Positive','Positive. A USD6 bn backstop for BNM in a dollar squeeze; no direct channel to Bank Muamalat funding or DRB-HICOM hedging.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (60,11,'Banking/Financial Services',38,'Malaysia Requires USD852 bn to USD1.1 tn for Climate Adaptation by 2050.','The Edge','15 Sept 2026',NULL,'The Securities Commission Malaysia chairman, citing a World Bank report, estimated that Malaysia needs USD852 bn to USD1.1 tn for climate adaptation by 2050. Limited standalone cash flows make many projects difficult to finance, increasing the need for blended finance and risk-mitigation structures.','Neutral','Neutral. A national estimate, not a procurement pipeline. Water and flood projects are the opening for MMC Engineering and Aliran Ihsan Resources Bhd (AIRB); Bank Muamalat needs bankable structures before it lends.',NULL,NULL,'2026-09-24 11:56:17');
INSERT INTO brief_rows (id,brief_id,sector,row_order,headline,source_name,source_date,source_url,summary,impact_grade,impact_text,regulatory_text,entities,created_at) VALUES (61,11,'Banking/Financial Services',39,'SC Defers Mandatory Emissions Assurance to 2028.','Business Today','17 Sept 2026',NULL,'The Advisory Committee on Sustainability Reporting (ACSR), chaired by the Securities Commission Malaysia (SC), pushed mandatory reasonable assurance of Scope 1 and Scope 2 greenhouse gas (GHG) emissions for Group 1 issuers to financial years from 1 Jan 2028, and to 2029 and 2030 for Groups 2 and 3. A review of the first 91 Group 1 issuers found disclosure quality needs improvement.','Neutral','Neutral. Listed Group entities gain an extra reporting cycle to fix emissions data before assurance becomes mandatory; confirm which of them sit in Group 1.','ISSA 5000 becomes the designated assurance standard, replacing ISAE 3000 (Revised) and ISO standards.',NULL,'2026-09-24 11:56:17');
